import React, { useEffect, useEffectEvent, useMemo, useState } from 'react';

export default function App() {
  const eventos = useMemo(() => new EventTarget(), []);
  const [tema, setTema] = useState('Claro');
  const [resultado, setResultado] = useState('Todavía sin eventos');

  const registrar = useEffectEvent(() => {
    setResultado('Tema al recibir el evento: ' + tema);
  });

  useEffect(() => {
    function onPing() {
      registrar();
    }

    eventos.addEventListener('ping', onPing);
    return () => eventos.removeEventListener('ping', onPing);
  }, [eventos]);

  return (
    <section>
      <h1>Tema: {tema}</h1>
      <button onClick={() => setTema(tema === 'Claro' ? 'Oscuro' : 'Claro')}>
        Cambiar tema
      </button>
      <button onClick={() => eventos.dispatchEvent(new Event('ping'))}>
        Emitir evento
      </button>
      <p aria-live="polite">{resultado}</p>
    </section>
  );
}

